-- doc_id: R10 · 원천 대비 건수·금액·최신성 대사 근거(읽기 전용) · 설명 = 30_현업요청대응/R10_데이터검증.md
-- 기준: 같은 세션 시각(CURRENT_TIMESTAMP) · 세션 TIMEZONE · 필터 = 각 블록 주석
-- Q01 회비: BRONZE_CRM.TM_PM_MBRFEE_ACMSLT ↔ SILVER.CRM_PAYMENT_BILLING (회비월 최근 6개월 · 건수·청구액·납입액)
WITH b AS (SELECT MBRFEE_MT m, COUNT(*) n, SUM(RQEST_AMT) rq, SUM(PAY_AMT) pa FROM GN_DW.BRONZE_CRM.TM_PM_MBRFEE_ACMSLT WHERE MBRFEE_MT >= TO_CHAR(DATEADD(month,-6,CURRENT_DATE),'YYYYMM') GROUP BY 1),
s AS (SELECT MBRFEE_MT m, COUNT(*) n, SUM(RQEST_AMT) rq, SUM(PAY_AMT) pa FROM GN_DW.SILVER.CRM_PAYMENT_BILLING WHERE MBRFEE_MT >= TO_CHAR(DATEADD(month,-6,CURRENT_DATE),'YYYYMM') GROUP BY 1)
SELECT COALESCE(b.m,s.m) mbrfee_mt, b.n bronze_n, s.n silver_n, s.n-b.n diff_n, b.rq bronze_rqest, s.rq silver_rqest, s.rq-b.rq diff_rqest, b.pa bronze_pay, s.pa silver_pay, s.pa-b.pa diff_pay FROM b FULL JOIN s ON b.m=s.m ORDER BY 1;
-- Q02 회비: SILVER.CRM_PAYMENT_BILLING ↔ GOLD.FACT_MEMBER_FEE (회비월 최근 6개월 · 청구액·납입액)
WITH s AS (SELECT MBRFEE_MT m, SUM(RQEST_AMT) rq, SUM(PAY_AMT) pa FROM GN_DW.SILVER.CRM_PAYMENT_BILLING WHERE MBRFEE_MT >= TO_CHAR(DATEADD(month,-6,CURRENT_DATE),'YYYYMM') GROUP BY 1),
g AS (SELECT TO_CHAR(MONTH_KEY) m, SUM(BILLED_AMT) rq, SUM(PAID_FEE) pa, SUM(BILLING_ROWS) rows_ FROM GN_DW.GOLD.FACT_MEMBER_FEE WHERE TO_CHAR(MONTH_KEY) >= TO_CHAR(DATEADD(month,-6,CURRENT_DATE),'YYYYMM') GROUP BY 1)
SELECT COALESCE(s.m,g.m) mbrfee_mt, s.rq silver_rqest, g.rq gold_billed, g.rq-s.rq diff_billed, s.pa silver_pay, g.pa gold_paid, g.pa-s.pa diff_paid, g.rows_ gold_billing_rows FROM s FULL JOIN g ON s.m=g.m ORDER BY 1;
-- Q03 예산: BRONZE_ERP.BDGT_ACMSLT_LEDGER ↔ GOLD.FACT_BUDGET (연도별 집행 총액 · 지출만)
WITH b AS (SELECT YEAR::VARCHAR y, COUNT(*) n, SUM(EXEC_TOT_AMT) ex FROM GN_DW.BRONZE_ERP.BDGT_ACMSLT_LEDGER GROUP BY 1),
g AS (SELECT LEFT(TO_CHAR(MONTH_KEY),4) y, COUNT(*) n, SUM(EXEC_BUDGET_ERP) ex FROM GN_DW.GOLD.FACT_BUDGET GROUP BY 1)
SELECT COALESCE(b.y,g.y) yr, b.n bronze_rows, g.n gold_rows, b.ex bronze_exec, g.ex gold_exec_erp, g.ex-b.ex diff_exec FROM b FULL JOIN g ON b.y=g.y ORDER BY 1;
-- Q04 회원 마스터: BRONZE ↔ SILVER ↔ GOLD 건수
SELECT (SELECT COUNT(*) FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_INFO) bronze_mber_info, (SELECT COUNT(DISTINCT MBER_NO) FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_INFO) bronze_distinct, (SELECT COUNT(*) FROM GN_DW.SILVER.CRM_MEMBER) silver_crm_member, (SELECT COUNT(*) FROM GN_DW.GOLD.DIM_MEMBER) gold_dim_member;
-- Q05 레이어별 행수 대응(같은 원천 1:1 테이블 · 차이 = 정제 규칙)
SELECT 'AGENCY_DGT' k, (SELECT COUNT(*) FROM GN_DW.BRONZE_AGENCY.DGT_AD_CMPGN_DTLS) bronze, (SELECT COUNT(*) FROM GN_DW.SILVER.AGENCY_AD_DIGITAL) silver, (SELECT COUNT(*) FROM GN_DW.GOLD.FACT_AD_DIGITAL) gold
UNION ALL SELECT 'AGENCY_VIDEO', (SELECT COUNT(*) FROM GN_DW.BRONZE_AGENCY.VIDEO_AD_CMPGN_DTLS), (SELECT COUNT(*) FROM GN_DW.SILVER.AGENCY_AD_ROW_VIDEO), NULL
UNION ALL SELECT 'AGENCY_REBRDC', (SELECT COUNT(*) FROM GN_DW.BRONZE_AGENCY.REBRDC_AD_CMPGN_DTLS), (SELECT COUNT(*) FROM GN_DW.SILVER.AGENCY_AD_ROW_REBRDC), NULL
UNION ALL SELECT 'AGENCY_BROADCAST(VIDEO+REBRDC)', (SELECT COUNT(*) FROM GN_DW.BRONZE_AGENCY.VIDEO_AD_CMPGN_DTLS) + (SELECT COUNT(*) FROM GN_DW.BRONZE_AGENCY.REBRDC_AD_CMPGN_DTLS), (SELECT COUNT(*) FROM GN_DW.SILVER.AGENCY_AD_ROW_VIDEO) + (SELECT COUNT(*) FROM GN_DW.SILVER.AGENCY_AD_ROW_REBRDC), (SELECT COUNT(*) FROM GN_DW.GOLD.FACT_AD_BROADCAST)  -- [2026-10-26] GOLD FACT_AD_BROADCAST = 영상 + 재방송 합본(U7 해소 · 종전 영상 단독 비교는 범위 오류)
UNION ALL SELECT 'ERP_EXPENSE', (SELECT COUNT(*) FROM GN_DW.BRONZE_ERP.EXPENSE_RESOLUTION), (SELECT COUNT(*) FROM GN_DW.SILVER.ERP_EXPENSE_RESOLUTION), (SELECT COUNT(*) FROM GN_DW.GOLD.FACT_EXPENSE_RESOLUTION)
UNION ALL SELECT 'GSC', (SELECT COUNT(*) FROM GN_DW.BRONZE_GSC.SEARCH_CONSOLE_DATA), (SELECT COUNT(*) FROM GN_DW.SILVER.SEARCH_CONSOLE_DATA), (SELECT COUNT(*) FROM GN_DW.GOLD.FACT_SEARCH_CONSOLE)
UNION ALL SELECT 'GA4_DEMO', (SELECT COUNT(*) FROM GN_DW.BRONZE_GA4.GA4_USER_DEMOGRAPHIC), (SELECT COUNT(*) FROM GN_DW.SILVER.GA4_USER_DEMOGRAPHIC), (SELECT COUNT(*) FROM GN_DW.GOLD.FACT_GA4_DEMOGRAPHIC)
UNION ALL SELECT 'CRM_MEMBER_DEV', (SELECT COUNT(*) FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_DVLP_AMT), (SELECT COUNT(*) FROM GN_DW.SILVER.CRM_MEMBER_DEV), NULL
UNION ALL SELECT 'CRM_SEND', (SELECT COUNT(*) FROM GN_DW.BRONZE_CRM.SND_MEMBER_LIST), (SELECT COUNT(*) FROM GN_DW.SILVER.CRM_SEND_MEMBER), (SELECT COUNT(*) FROM GN_DW.GOLD.FACT_MESSAGE_DISPATCH);
-- Q06 최신성: 레이어별 적재 시각 · 원천 기준일
SELECT 'BRONZE_CRM.TM_PM_MBRFEE_ACMSLT' t, MAX(_LOAD_DT)::VARCHAR last_load, MAX(MBRFEE_MT) max_biz_key FROM GN_DW.BRONZE_CRM.TM_PM_MBRFEE_ACMSLT
UNION ALL SELECT 'SILVER.CRM_PAYMENT_BILLING', MAX(DW_LOAD_TS)::VARCHAR, MAX(MBRFEE_MT) FROM GN_DW.SILVER.CRM_PAYMENT_BILLING
UNION ALL SELECT 'GOLD.FACT_MEMBER_FEE', MAX(DW_LOAD_TS)::VARCHAR, MAX(MONTH_KEY)::VARCHAR FROM GN_DW.GOLD.FACT_MEMBER_FEE
UNION ALL SELECT 'GOLD.FACT_BUDGET', MAX(DW_LOAD_TS)::VARCHAR, MAX(MONTH_KEY)::VARCHAR FROM GN_DW.GOLD.FACT_BUDGET
UNION ALL SELECT 'MSTR.F_MM_SPNSR_DVLP_SUM', NULL, (SELECT MAX(STRD_MT)::VARCHAR FROM GN_DW.MSTR.F_MM_SPNSR_DVLP_SUM);
-- Q07 PK 중복·NULL (GOLD 핵심 팩트 · 키 = dbt unique_key / grain)
SELECT 'FACT_MEMBER_MONTHLY null MEMBER_DK' chk, COUNT_IF(MEMBER_DK IS NULL) v FROM GN_DW.GOLD.FACT_MEMBER_MONTHLY
UNION ALL SELECT 'DIM_MEMBER dup MEMBER_DK', COUNT(*)-COUNT(DISTINCT MEMBER_DK) FROM GN_DW.GOLD.DIM_MEMBER
UNION ALL SELECT 'DIM_CAMPAIGN dup CAMPAIGN_SK', COUNT(*)-COUNT(DISTINCT CAMPAIGN_SK) FROM GN_DW.GOLD.DIM_CAMPAIGN;
-- Q08 차이 사유 검증(회비): GOLD MONTH_KEY = COALESCE(회비월, 납입월) ⇒ 회비월이 비거나 다른 납입이 납입월로 들어간다. SILVER 를 같은 규칙으로 다시 묶으면 GOLD 와 같아야 한다
WITH s AS (SELECT COALESCE(TRY_TO_NUMBER(MBRFEE_MT), TRY_TO_NUMBER(TO_CHAR(PAY_DE,'YYYYMM'))) m, SUM(PAY_AMT) pa, SUM(IFF(MBRFEE_MT IS NULL, PAY_AMT, 0)) pa_no_mt, SUM(IFF(PAYMENT_TYPE='회비',PAY_AMT,0)) pa_fee FROM GN_DW.SILVER.CRM_PAYMENT_BILLING WHERE MBER_NO IS NOT NULL GROUP BY 1),
g AS (SELECT MONTH_KEY m, SUM(PAID_FEE) pa, SUM(PAID_FEE_BILLABLE) pa_fee FROM GN_DW.GOLD.FACT_MEMBER_FEE GROUP BY 1)
SELECT g.m month_key, s.pa silver_pay_same_rule, g.pa gold_paid, g.pa-s.pa diff_paid, s.pa_no_mt silver_pay_without_mbrfee_mt, s.pa_fee silver_pay_fee_only, g.pa_fee gold_paid_billable FROM g LEFT JOIN s ON s.m=g.m WHERE g.m BETWEEN TO_NUMBER(TO_CHAR(DATEADD(month,-6,CURRENT_DATE),'YYYYMM')) AND TO_NUMBER(TO_CHAR(CURRENT_DATE,'YYYYMM')) ORDER BY 1;
-- Q09 차이 사유 검증(예산): BRONZE 에서 합계행(INCOME_EXPS_DIV_NM='TOTAL')을 빼면 GOLD 와 같아야 한다(macro gn_erp_not_total)
WITH b AS (SELECT YEAR::VARCHAR y, SUM(IFF(INCOME_EXPS_DIV_NM='TOTAL',EXEC_TOT_AMT,0)) total_rows_exec, SUM(IFF(INCOME_EXPS_DIV_NM<>'TOTAL',EXEC_TOT_AMT,0)) detail_exec, SUM(IFF(INCOME_EXPS_DIV_NM<>'TOTAL',EXEC_AMT_1+EXEC_AMT_2+EXEC_AMT_3+EXEC_AMT_4+EXEC_AMT_5+EXEC_AMT_6+EXEC_AMT_7+EXEC_AMT_8+EXEC_AMT_9+EXEC_AMT_10+EXEC_AMT_11+EXEC_AMT_12,0)) detail_exec_month_sum FROM GN_DW.BRONZE_ERP.BDGT_ACMSLT_LEDGER GROUP BY 1),
g AS (SELECT LEFT(TO_CHAR(MONTH_KEY),4) y, SUM(EXEC_BUDGET_ERP) ex FROM GN_DW.GOLD.FACT_BUDGET GROUP BY 1)
SELECT b.y yr, b.total_rows_exec, b.detail_exec, b.detail_exec_month_sum, g.ex gold_exec_erp, g.ex-b.detail_exec_month_sum diff_vs_month_sum FROM b LEFT JOIN g ON b.y=g.y ORDER BY 1;
-- Q10 차이 사유 검증(발송): BRONZE_CRM.SND_MEMBER_LIST 만이 아니라 채널별 발송 원천 4종을 합친다(SILVER.CRM_SEND_MEMBER)
SELECT (SELECT COUNT(*) FROM GN_DW.BRONZE_CRM.SND_MEMBER_LIST) snd, (SELECT COUNT(*) FROM GN_DW.BRONZE_CRM.TD_MS_EMAIL_SNDNG_DTLS) email, (SELECT COUNT(*) FROM GN_DW.BRONZE_CRM.TD_MS_MSG_AT_SNDNG_DTLS) alimtalk, (SELECT COUNT(*) FROM GN_DW.BRONZE_CRM.TD_MS_PSTMTR_SNDNG_DTL) post, (SELECT COUNT(*) FROM GN_DW.SILVER.CRM_SEND_MEMBER) silver_send_member;
-- Q11 차이 사유 검증(예산 절차): BRONZE 는 같은 연도를 연사업·추가경정 두 절차로 싣는다 ⇒ 절차별 집행액과 GOLD 집행액 대조
WITH b AS (SELECT YEAR::VARCHAR y, BDGT_PRCD_NM prcd, COUNT(*) n, SUM(EXEC_TOT_AMT) ex_tot, SUM(EXEC_AMT_1+EXEC_AMT_2+EXEC_AMT_3+EXEC_AMT_4+EXEC_AMT_5+EXEC_AMT_6+EXEC_AMT_7+EXEC_AMT_8+EXEC_AMT_9+EXEC_AMT_10+EXEC_AMT_11+EXEC_AMT_12) ex_month_sum FROM GN_DW.BRONZE_ERP.BDGT_ACMSLT_LEDGER GROUP BY 1,2),
g AS (SELECT LEFT(TO_CHAR(MONTH_KEY),4) y, BUDGET_PROCEDURE prcd, COUNT(*) n, SUM(EXEC_BUDGET_ERP) ex FROM GN_DW.GOLD.FACT_BUDGET GROUP BY 1,2)
SELECT COALESCE(b.y,g.y) yr, COALESCE(b.prcd,g.prcd) procedure_nm, b.n bronze_rows, b.ex_tot bronze_exec_tot, b.ex_month_sum bronze_exec_month_sum, g.n gold_rows, g.ex gold_exec_erp FROM b FULL JOIN g ON b.y=g.y AND b.prcd=g.prcd ORDER BY 1,2;
-- Q12 차이 사유 분해(소량 건수): ① 영상광고 빈 행 ② 회원개발 PK NULL·고아 회원 ③ 발송 PK NULL·중복·고아 회원
SELECT 'VIDEO_ALL_NULL_ROW' k, COUNT_IF(ARRAY_SIZE(OBJECT_KEYS(OBJECT_CONSTRUCT(*)))=0) v FROM GN_DW.BRONZE_AGENCY.VIDEO_AD_CMPGN_DTLS
UNION ALL SELECT 'DEV_PK_NULL', COUNT_IF(SPNSR_NO IS NULL OR SPNSR_BSNS_NO IS NULL OR OCCRRNC_DE IS NULL OR SER_NO IS NULL) FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_DVLP_AMT
UNION ALL SELECT 'DEV_ORPHAN_MEMBER', COUNT(*) FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_DVLP_AMT d WHERE d.SPNSR_NO IS NOT NULL AND d.SPNSR_BSNS_NO IS NOT NULL AND d.OCCRRNC_DE IS NOT NULL AND d.SER_NO IS NOT NULL AND NOT EXISTS (SELECT 1 FROM GN_DW.SILVER.CRM_MEMBER m WHERE m.MEMBER_DK = d.MBER_NO)
UNION ALL SELECT 'SND_PK_NULL', COUNT_IF(REQ_SEQ_NO IS NULL OR R_NUM IS NULL) FROM GN_DW.BRONZE_CRM.SND_MEMBER_LIST
UNION ALL SELECT 'SND_DUP', COUNT(*) - COUNT(DISTINCT REQ_SEQ_NO, R_NUM) FROM GN_DW.BRONZE_CRM.SND_MEMBER_LIST WHERE REQ_SEQ_NO IS NOT NULL AND R_NUM IS NOT NULL
UNION ALL SELECT 'EMAIL_DUP_OR_NULL', COUNT(*) - COUNT(DISTINCT IFF(SNDNG_KEY IS NULL OR SNDNG_DTL_KEY IS NULL, NULL, SNDNG_KEY||'|'||SNDNG_DTL_KEY)) FROM GN_DW.BRONZE_CRM.TD_MS_EMAIL_SNDNG_DTLS
UNION ALL SELECT 'MSG_AT_DUP_OR_NULL', COUNT(*) - COUNT(DISTINCT IFF(SNDNG_KEY IS NULL OR SNDNG_DTL_KEY IS NULL, NULL, SNDNG_KEY||'|'||SNDNG_DTL_KEY)) FROM GN_DW.BRONZE_CRM.TD_MS_MSG_AT_SNDNG_DTLS
UNION ALL SELECT 'POST_DUP_OR_NULL', COUNT(*) - COUNT(DISTINCT IFF(SNDNG_KEY IS NULL OR SNDNG_DTL_KEY IS NULL, NULL, SNDNG_KEY||'|'||SNDNG_DTL_KEY)) FROM GN_DW.BRONZE_CRM.TD_MS_PSTMTR_SNDNG_DTL;
